{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "A systematic literature review is presented here, to identify available models for malaria control optimization for resource allocation in limited resource settings, determine how they have been used and to assess them for quality and utility. The research question for this review was ' Are there English-language publications in peer-reviewed scientific journals describing how models have been used to allocate resources for malaria interventions in limited resource settings?' The main aim of this review was to identify and characterize models for malaria control optimization for resource allocation in malaria control and elimination settings and to identify their strengths and limitations.",
      "reason": "The review provides an explicit objective/aim statement and also an explicit research question addressing what the review will identify and assess."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_6",
      "quote": "A systematic literature review is presented here, to identify available models for malaria control optimization for resource allocation in limited resource settings, determine how they have been used and to assess them for quality and utility. The research question for this review was ' Are there English-language publications in peer-reviewed scientific journals describing how models have been used to allocate resources for malaria interventions in limited resource settings?' The main aim of this review was to identify and characterize models for malaria control optimization for resource allocation in malaria control and elimination settings and to identify their strengths and limitations.",
      "reason": "The evidence describes objectives focused on identifying/characterizing optimization models and assessing their quality/utility, not planned comparisons of intervention effects using PICO (or a variant). Therefore, this PICO-based comparisons requirement does not apply to the review as described."
    }
  ],
  "confidence": 78
}

